      options: { indexAxis: 'y', layout: { padding: { right: 50 } }, plugins: { legend: { display: false }, tooltip: { callbacks: { label: function (c) { return c.raw.toFixed(3) + ' of R² ' + D.r2; } } } }, scales: { x: Object.assign(axis({ title: 'contribution to R²' }), { min: 0, max: 0.22 }), y: axis({ grid: false }) } },
